def components_where(grid, pred, conn8=False):
 H=len(grid);W=len(grid[0]); seen=set();comps=[]
 dirs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0)] if conn8 else [(1,0),(-1,0),(0,1),(0,-1)]
 for r in range(H):
  for c in range(W):
   if pred(grid[r][c]) and (r,c) not in seen:
    stack=[(r,c)];seen.add((r,c));co=[]
    while stack:
     p=stack.pop();co.append(p)
     for dr,dc in dirs:
      nr,nc=p[0]+dr,p[1]+dc
      if 0<=nr<H and 0<=nc<W and pred(grid[nr][nc]) and (nr,nc) not in seen:
       seen.add((nr,nc));stack.append((nr,nc))
    comps.append(co)
 return comps
